class _FakeResponse:
    """Minimal stand-in for the object urlopen yields as a context manager."""

    def __init__(self, body: bytes, status: int = 200, ctype: str = "text/html"):
        self._body = body
        self.status = status
        self.headers = {"Content-Type": ctype}

    def read(self) -> bytes:
        return self._body

    def __enter__(self) -> "_FakeResponse":
        return self

    def __exit__(self, *exc: object) -> None:
        return None


def _html(text: str) -> bytes:
    """HTML whose extracted text clears MIN_HTML_CHARS.

    `render` now downgrades a near-empty HTML extraction to FAILED, so a
    fixture that is realistic prose rather than three words is required to
    exercise the success path at all.
    """
    filler = " Padding sentence to clear the minimum body length threshold."
    return f"<p>{text}</p><p>{filler * 5}</p>".encode()


def _raise_http(code: int, body: str):
    """Build a urlopen replacement that raises HTTPError with `body`."""

    class _Err(urllib.error.HTTPError):
        def __init__(self) -> None:
            hdrs: dict = {}
            super().__init__(
                "http://svc/fetch", code, "err", hdrs, None  # type: ignore[arg-type]
            )

        def read(self) -> bytes:  # type: ignore[override]
            return body.encode()

    def _fake(*args: object, **kwargs: object):
        raise _Err()

    return _fake


