# OCR fallback for scanned PDFs


def _scanned_pdf(lines: list[str]) -> bytes:
    """A PDF whose pages are images — no text layer, like a real scan."""
    from PIL import Image, ImageDraw, ImageFont

    img = Image.new("RGB", (1240, 120 + 70 * len(lines)), "white")
    draw = ImageDraw.Draw(img)
    font = ImageFont.load_default(size=34)
    for i, line in enumerate(lines):
        draw.text((40, 40 + i * 70), line, fill="black", font=font)
    buf = io.BytesIO()
    img.save(buf, format="PDF", resolution=150)
    return buf.getvalue()


def _has_ocr() -> bool:
    import importlib.util

    return all(
        importlib.util.find_spec(m) is not None
        for m in ("pypdfium2", "rapidocr_onnxruntime", "PIL")
    )


ocr_only = pytest.mark.skipif(not _has_ocr(), reason='needs pip install -e ".[ocr]"')


@ocr_only
def test_scanned_pdf_is_read_by_ocr() -> None:
    raw = _scanned_pdf(["Artigo 17.o-A do CIMT", "A taxa e de 7,5% sobre o valor."])
    out = fetch_url.render("https://x.test/scan.pdf", "OK", "application/pdf", raw)
    assert "7,5%" in out
    assert "CIMT" in out


@ocr_only
def test_ocr_output_is_marked_as_a_transcription() -> None:
    """An audit agent must not read OCR text as a quotable source string.

    A misread digit produces a plausible wrong number, and the audit compares
    the deliverable against this same file — so the error would be confirmed,
    not caught. The status line is the only thing standing in the way.
    """
    raw = _scanned_pdf(["Coima ate EUR 20.000"])
    out = fetch_url.render("https://x.test/scan.pdf", "OK", "application/pdf", raw)
    status = out.splitlines()[2]
    assert status.startswith("# Status: OK (OCR")
    assert "transcription, not verbatim source" in status


@ocr_only
def test_ocr_reports_truncation(monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.setattr(fetch_url, "MAX_OCR_PAGES", 1)
    from PIL import Image

    page = Image.new("RGB", (400, 200), "white")
    buf = io.BytesIO()
    page.save(buf, format="PDF", save_all=True, append_images=[page])
    out = fetch_url.ocr_pdf(buf.getvalue())[0]
    assert "truncated at 1 of 2 pages" in out or out.startswith("FAILED")


def test_ocr_absence_names_the_install(monkeypatch: pytest.MonkeyPatch) -> None:
    """Without the extra, a scanned PDF must say so and say how to fix it."""
    monkeypatch.setitem(sys.modules, "pypdfium2", None)
    status, body = fetch_url.ocr_pdf(b"%PDF-1.7")
    assert status.startswith("FAILED (no text layer")
    assert 'pip install -e ".[ocr]"' in status
    assert body == ""


def test_ocr_render_failure_is_recorded_not_raised() -> None:
    status, body = fetch_url.ocr_pdf(b"not a pdf at all")
    assert status.startswith("FAILED (")
    assert body == ""


# ---------------------------------------------------------------------------
# Dependency preflight — catch a missing extractor before the run, not after


def test_check_dependencies_flags_missing_required(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    import importlib.util

    real = importlib.util.find_spec
    monkeypatch.setattr(
        importlib.util, "find_spec", lambda n: None if n == "pypdf" else real(n)
    )
    lines, ok = fetch_url.check_dependencies()
    assert not ok
    assert any("MISSING  pypdf" in line for line in lines)
    assert any("pip install -e ." in line for line in lines)


def test_check_dependencies_optional_absence_is_not_a_failure(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """No OCR extra is a reduced capability, not a broken install."""
    import importlib.util

    real = importlib.util.find_spec
    monkeypatch.setattr(
        importlib.util,
        "find_spec",
        lambda n: None if n in ("pypdfium2", "rapidocr_onnxruntime") else real(n),
    )
    lines, ok = fetch_url.check_dependencies()
    assert ok
    assert any('pip install -e ".[ocr]"' in line for line in lines)


def test_check_exits_3_when_a_required_dependency_is_missing(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """A healthy service with no PDF extractor is still a failed preflight."""
    monkeypatch.setattr(fetch_url, "check_service", lambda: 0)
    monkeypatch.setattr(fetch_url, "check_dependencies", lambda: (["MISSING"], False))
    with patch.object(sys, "argv", ["fetch_url", "--check"]):
        with pytest.raises(SystemExit) as exc:
            fetch_url.main()
    assert exc.value.code == 3
